def _linalg_inv_kernel(
    A,
    INV,
    INFO,
    PIVOTS,
    N: tl.constexpr,
    BLOCK_N: tl.constexpr,
    COL_TILE: tl.constexpr,
):
    """LU factorisation + triangular solve, mirroring the reference arithmetic.

    The reference op on this target is a CPU LAPACK fallback.  Its solve path
    hands LAPACK the row-major buffer with trans='T', so LAPACK factors
    ``M = A^T`` (not A) and solves ``A x = b`` via ``getrs(trans='T')``:
    ``U^T y = P b`` followed by ``L^T z = y``.  Factoring A^T matters
    numerically: an exactly singular A (duplicated rows) has *identical
    columns* in A^T, so the trailing pivot is a tiny cancellation residual
    rather than an exact zero -- which is exactly why the reference reports
    info == 0 together with huge finite inverse entries.

    Each program instance handles one matrix in the batch.
    Phase 1: P*M = L*U with partial pivoting (multipliers via reciprocal
    multiply, as LAPACK's getf2 does when |pivot| >= SFMIN).
    Phase 2: solve M^T z = e_j in tiles of COL_TILE right-hand sides.
    """
    pid = tl.program_id(0)
    rows = tl.arange(0, BLOCK_N)
    cols = tl.arange(0, BLOCK_N)

    # Load M = A^T : work[r, c] = A[c, r]
    mask = (rows[:, None] < N) & (cols[None, :] < N)
    offsets = pid * N * N + cols[None, :] * N + rows[:, None]
    work = tl.load(A + offsets, mask=mask, other=0.0).to(tl.float32)

    pivot_base = pid * N
    singular = 0
    col_mask = cols[None, :] < N

    # Phase 1: LU factorisation of M with partial pivoting
    for j_ind in tl.range(0, N):
        # Pivot search: first index of the maximum |column j|
        col_j = tl.sum(tl.where(cols[None, :] == j_ind, work, 0.0), axis=1)
        abs_col = tl.abs(col_j)
        abs_col = tl.where(rows < j_ind, -1.0, abs_col)
        abs_col = tl.where(rows < N, abs_col, -1.0)
        pivot_val = tl.max(abs_col, axis=0)
        pivot_row = tl.min(tl.where(abs_col == pivot_val, rows, BLOCK_N), axis=0)

        tl.store(PIVOTS + pivot_base + j_ind, pivot_row)

        # Row swap (dlaswp semantics)
        row_j = tl.sum(tl.where(rows[:, None] == j_ind, work, 0.0), axis=0)
        row_p = tl.sum(tl.where(rows[:, None] == pivot_row, work, 0.0), axis=0)
        work = tl.where((rows[:, None] == j_ind) & col_mask, row_p, work)
        work = tl.where((rows[:, None] == pivot_row) & col_mask, row_j, work)

        pivot = tl.sum(
            tl.sum(
                tl.where(
                    (rows[:, None] == j_ind) & (cols[None, :] == j_ind),
                    work,
                    0.0,
                ),
                axis=0,
            ),
            axis=0,
        )

        singular = tl.where((pivot == 0.0) & (singular == 0), j_ind + 1, singular)

        # Multipliers: LAPACK scales the column by 1/pivot (reciprocal
        # multiply) instead of dividing; this changes the last bits and hence
        # the tiny residual pivots of a numerically singular matrix.
        col_vals = tl.sum(tl.where(cols[None, :] == j_ind, work, 0.0), axis=1)
        rcp = 1.0 / pivot
        multipliers = tl.where(rows > j_ind, col_vals * rcp, 0.0)

        work = tl.where(
            (rows[:, None] > j_ind) & (cols[None, :] == j_ind),
            multipliers[:, None],
            work,
        )

        # Trailing rank-1 update (dger). Written as a separate multiply and
        # subtract: the reference (MKL dger) rounds the product before the
        # subtraction, and that last-bit behaviour decides the tiny residual
        # pivots of a numerically singular matrix.
        u_row = tl.sum(tl.where(rows[:, None] == j_ind, work, 0.0), axis=0)
        update_mask = (rows[:, None] > j_ind) & (cols[None, :] > j_ind)
        prod = multipliers[:, None] * u_row[None, :]
        work = tl.where(update_mask, work - prod, work)

    # Phase 2: solve M^T z = e_j in column tiles of right-hand sides
    tile_cols = tl.arange(0, COL_TILE)

    for tile_start in tl.range(0, N, COL_TILE):
        rhs = tl.where(rows[:, None] == (tile_start + tile_cols[None, :]), 1.0, 0.0)
        tile_mask = tile_cols[None, :] < COL_TILE

        # Permutation (dlaswp)
        for j_perm in tl.range(0, N):
            piv_row = tl.load(PIVOTS + pivot_base + j_perm)
            rhs_row_j = tl.sum(tl.where(rows[:, None] == j_perm, rhs, 0.0), axis=0)
            rhs_row_p = tl.sum(tl.where(rows[:, None] == piv_row, rhs, 0.0), axis=0)
            rhs = tl.where(
                (rows[:, None] == j_perm) & tile_mask,
                rhs_row_p[None, :],
                rhs,
            )
            rhs = tl.where(
                (rows[:, None] == piv_row) & tile_mask,
                rhs_row_j[None, :],
                rhs,
            )

        # U^T y = P b : forward substitution, dividing by the U diagonal
        for j_fwd in tl.range(0, N):
            diag_val = tl.sum(
                tl.sum(
                    tl.where(
                        (rows[:, None] == j_fwd) & (cols[None, :] == j_fwd),
                        work,
                        0.0,
                    ),
                    axis=0,
                ),
                axis=0,
            )
            rhs_row_j = tl.sum(tl.where(rows[:, None] == j_fwd, rhs, 0.0), axis=0)
            scaled_row = rhs_row_j / diag_val
            rhs = tl.where(
                (rows[:, None] == j_fwd) & tile_mask,
                scaled_row[None, :],
                rhs,
            )
            u_row = tl.sum(tl.where(rows[:, None] == j_fwd, work, 0.0), axis=0)
            u_row = tl.where(rows > j_fwd, u_row, 0.0)
            rhs = rhs - u_row[:, None] * scaled_row[None, :]

        # L^T z = y : unit-triangular back substitution (no division).
        # x_p += -L[j, p] * x_j for p < j, i.e. row j of the factors, entries
        # left of the diagonal (getrs trans='T' push form).
        for j_rev in tl.range(0, N):
            j_back = N - 1 - j_rev
            z_row = tl.sum(tl.where(rows[:, None] == j_back, rhs, 0.0), axis=0)
            l_row = tl.sum(tl.where(rows[:, None] == j_back, work, 0.0), axis=0)
            l_row = tl.where(cols < j_back, l_row, 0.0)
            rhs = rhs - l_row[:, None] * z_row[None, :]

        out_offsets = (
            pid * N * N + rows[:, None] * N + (tile_start + tile_cols[None, :])
        )
        out_mask = (rows[:, None] < N) & ((tile_start + tile_cols[None, :]) < N)
        tl.store(INV + out_offsets, rhs, mask=out_mask)

    tl.store(INFO + pid, singular)


def linalg_inv_ex(A, *, check_errors=False):
    """Compute the inverse of a square matrix.

    Args:
        A: Input tensor of shape (*, n, n).
        check_errors: If True, raises an error if the matrix is singular.

    Returns:
        A namedtuple (inverse, info) where:
        - inverse: The inverse matrix of shape (*, n, n).
        - info: An int32 tensor. 0 indicates success; a positive integer i
          indicates that the i-th diagonal element of U in the LU
          decomposition is exactly zero.
    """
    logger.debug("GEMS LINALG_INV_EX")
    assert A.ndim >= 2, "Input must be at least 2D"
    n = A.shape[-1]
    assert A.shape[-2] == n, "Input must be a square matrix"
    assert A.dtype in (
        torch.float32,
        torch.float64,
    ), f"linalg_inv_ex: unsupported dtype {A.dtype}, requires float32 or float64"

    device = A.device
    dtype = A.dtype
    batch_shape = A.shape[:-2]
    batch_size = 1
    for s in batch_shape:
        batch_size *= s

    # Flatten batch dimensions
    A_flat = A.contiguous().reshape(batch_size, n, n)

    block_n = triton.next_power_of_2(n)
    # Minimum block size of 4 to avoid Triton codegen edge cases with tiny blocks
    block_n = max(block_n, 4)

    # Choose COL_TILE to control register pressure during the solve phase.
